import {noncombatRunning} from './noncombat-policy.js';
import {hasCanonicalEpilogue} from './otherworld-entitlement.js';
import {otherworldStatus,OTHERWORLD_LOOT_POLICY as LOOT,RARITY} from './engine.js';
import {formatAttribute as n,formatAttributePercent} from './attribute-format.js';
export function renderOtherworldPortal(s){return hasCanonicalEpilogue(s)?'<button class="otherworldPortal" data-otherworld="open" aria-label="异界通道 · 尾声已完成"><span class="otherworldPortalRing" aria-hidden="true">◇</span><strong>异界通道</strong><small>尾声之后 · 逐层深入</small></button>':'';}
export function renderOtherworldStone(s){if(!hasCanonicalEpilogue(s)||!s.otherworld?.stoneGranted)return '';const used=s.otherworld.stoneUsed,busy=noncombatRunning(s)||!!(s.activeEncounter&&!s.activeEncounter.rewarded)||!!s.story?.activeScene;return `<section class="panel otherworldStone" aria-label="异界之石"><span class="otherworldStoneIcon" aria-hidden="true">◆</span><div><h3>异界之石${used?' · 已使用':' ×1'}</h3><p>${used?'100级上限已解除。100级后每级7920经验，升级继续获得天赋点。':'尾声完成奖励。使用后永久解除100级上限；不补发经验，不自动升级。'}</p><small>专属保护道具 · 不可出售、丢弃或熔炼${!used&&busy?' · 请先结束战斗并停止挂机':''}</small></div>${used?'<b class="otherworldUsed">突破已生效</b>':`<button class="primary" data-otherworld="use-stone" ${busy?'disabled':''}>使用异界之石</button>`}</section>`;}
export function renderOtherworldPanel(s){if(!hasCanonicalEpilogue(s))return '';const o=otherworldStatus(s),max=Math.min(o.highestCleared+1,o.maxFloor),busy=!!(s.activeEncounter&&!s.activeEncounter.rewarded);return `<section class="panel otherworldPanel" aria-label="异界爬层控制"><div class="otherworldPanelTitle"><div><div class="eyebrow">尾声之后 · 独立挑战</div><h2>异界通道 <span>第 ${o.floor} 层</span></h2></div><strong>最高通关 ${o.highestCleared} 层</strong></div><p>异界守卫拥有较高基础属性；每层生命、攻击与护甲在上一层基础上提升 <b>1%</b>。</p><div class="otherworldStats"><span>生命 <b>${n(o.stats.hp)}</b></span><span>攻击 <b>${n(o.stats.atk)}</b></span><span>护甲 <b>${n(o.stats.armor)}</b></span><span>相对首层 <b>${formatAttributePercent(o.stats.scale)}</b></span></div><p class="otherworldLoot">每胜利必得${LOOT.gearPerWin}件${LOOT.equipmentLevel}级装备：${LOOT.rarities.map((q,i)=>RARITY[q]+' '+LOOT.qualityWeights[i]+'%').join(' / ')}；另有${LOOT.setChance*100}%概率获得全部种族池中的套装。经验${LOOT.xp}，金币${LOOT.gold}；不掉落传说、材料或消耗品。</p><div class="otherworldControls">${o.active?`<button data-otherworld="auto" aria-pressed="${o.autoAdvance}">${o.autoAdvance?'✓ 自动推进下一层':'固定本层刷取'}</button><label>选择层数 <input id="otherworldFloor" type="number" min="1" max="${max}" step="1" value="${o.floor}" aria-label="选择已解锁异界层数"></label><button data-otherworld="floor">${busy?'本场结束后换层':'切换层数'}</button><button data-otherworld="exit">${busy?'本场结束后退出':'退出异界'} · 保留原路线</button>`:'<button class="primary" data-otherworld="enter">进入异界 · 开始爬层</button>'}</div><p class="subtleText">可选择第1–${max}层；关闭自动推进即可反复刷取。本场结束后安全切换，不丢弃战斗奖励。退出后停止挂机，不会自动进入普通世界。</p>${o.pendingEquipment?`<div class="otherworldPending" role="status">待领取装备 <b>${o.pendingEquipment}</b> 件 · 背包满时安全保留<button data-otherworld="claim">领取可容纳装备</button></div>`:''}${o.storageBlocked?'<p role="status">待领取装备已满，请整理背包后领取，再继续挑战。</p>':''}</section>`;}
